window.SAQ_PAPER_QUESTIONS["2018-1-pah"]=[{"number":1,"title":"","stemText":"The ambulance service has called to alert you about the impending arrival of a critically unwell patient. You will be receiving a 25 year old man who has been stabbed once to the left side of his anterior chest with a large knife.\nHis vital signs with the ambulance are:\n\nGCS\nE4 V4 M6 Pulse 135 /min\n\nBP\n85/45 mmHg O2 sats 98% 15L O2 via non-rebreather mask The patient is reported to be agitated.","parts":[{"id":"a","label":"Part A","prompt":"List 4 critical interventions you would prepare to perform in the ED. For each intervention, give the clinical indication for its use. (8 marks) Critical intervention Clinical indication Upon arrival, a chest x-ray has been performed. The x-ray is provided in the PROPS BOOKLET."},{"id":"b","label":"Part B","prompt":"List the main pathology evident in the chest x-ray. (1 mark)"},{"id":"c","label":"Part C","prompt":"List 2 supporting radiographical features. (2 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List 2 other possible traumatic causes of the patient’s hypotension. For each, state the\nsupportive findings on examination or investigation. (4 marks) Cause of hypotension Examination or Investigative finding You have determined that an intercostal catheter needs to be inserted for management of this patient’s injuries."},{"id":"e","label":"Part E","prompt":"List 4 possible complications of the procedure and a safety step you would include in your technique to avoid each complication. (8 marks) Complication Safety step"}],"propPages":["asset:img41ef2f17ccfd0824a6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>17/23</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>-</td><td>Left thoracostomy / ICC insertion – for clinical or radiological evidence of pneumothorax or</td></tr><tr><td>haemothorax</td><td></td></tr><tr><td>-</td><td>ED thoracotomy – for cardiac arrest if signs of life in last 10 minutes</td></tr><tr><td>-</td><td>Blood administration – if inadequate mentation / radial pulse / systolic below 80mmHg</td></tr><tr><td>-</td><td>Intubation – if agitation impairing management, if hypoxic, if arrest or significantly</td></tr><tr><td>depressed level consciousness</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Left sided pneumothorax (accept tension – rib spaces are widened)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">- visible lung edge</div><div class=\"answer-line\">- rim of lucency aroung lung edge</div><div class=\"answer-line\">- widened rib spaces on left</div><div class=\"answer-line\">- deep sulcus sign</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>- pericardial tamponade – pericardial fluid on FAST, raised JVP</td><td>- intraperitoneal haemorrhage – intra-peritoneal fluid evident on FAST scan, tender abdomen</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">- extra-thoracic placement – ensure finger has entered thoracic space and guided passage of ICC</div><div class=\"answer-line\">- damage to intercostal vessels / nerve – ensure placement above rib not below</div><div class=\"answer-line\">- lung laceration – finger sweep on entering thoracic cavity, not use trocar</div><div class=\"answer-line\">- heart injury – avoid trocar, gentle insertion of ICC</div><div class=\"answer-line\">- diaphragm / abdominal organ injury – ensure placement in triangle of safety, lowest 5th interspace</div><div class=\"answer-line\">- infection – full sterile technique</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 45 year old man with known HIV has presented to the ED with shortness of breath.","parts":[{"id":"a","label":"Part A","prompt":"List 2 specific laboratory findings that would support a diagnosis of Acquired\nImmunodeficiency Syndrome (AIDS). (2 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 4 AIDS defining illnesses. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ Your assessment is consistent with pneumonia and severe immunodeficiency. The patient is moderately unwell and will require admission to hospital for intravenous antibiotics."},{"id":"c","label":"Part C","prompt":"List 3 key pathogens that must be considered in this situation. List the antibiotic you will choose to treat each pathogen. (6 marks) Pathogen Antibiotic"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">CD4 count &lt;200</div><div class=\"answer-line\">Viral load &gt;50 000</div><div class=\"answer-line\">Also accept absolute lymphocyte count &lt; 1200</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Also accept absolute lymphocyte count &lt; 1200</div><div class=\"answer-line\">Streptococcus pneumonie – benzylpenicillin, ceftriaxone</div><div class=\"answer-line\">Mycoplasma pneumonie or other atypical – azithromycin</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Streptococcus pneumonie – benzylpenicillin, ceftriaxone</div><div class=\"answer-line\">Mycoplasma pneumonie or other atypical – azithromycin</div><div class=\"answer-line\">Pneumocystis jiroveci – Co-trimoxazole</div><div class=\"answer-line\">Also accept Mycobacterium tuberculosis – and any TB drug</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 28 year old woman has presented to your ED with left lower quadrant abdominal pain.\nHer vital signs are:\n\nGCS\nPulse /min\n\nBP\n110/75 mmHg You are considering the differential diagnosis of ectopic pregnancy.","parts":[{"id":"a","label":"Part A","prompt":"List 5 risk factors that would increase the risk of ectopic pregnancy. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ A bedside urine qualitative beta-HCG test has returned positive. As part of your further assessment, you have elected to perform a quantitative serum beta-HCG level and a trans-vaginal USS."},{"id":"b","label":"Part B","prompt":"Complete the following table by indicating the relevance of the serum beta-HCG level to the interpretation of the USS and subsequent management. (4 marks) Serum b"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/9</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Previous ectopic</div><div class=\"answer-line\">IVF</div><div class=\"answer-line\">Hx PID</div><div class=\"answer-line\">Hx tubal surgery</div><div class=\"answer-line\">IUD</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Less than 1500</div><div class=\"answer-line\">may not see intra-uterine gestation at this early stage, so both ectopic and</div><div class=\"answer-line\">intra-uterine gestation possible if USS does not identify intra-uterine gestation, will need close</div><div class=\"answer-line\">follow up with repeat USS and HCG</div><div class=\"answer-line\">More than 1500</div><div class=\"answer-line\">Should see intra-uterine gestation, therefore if uterus is empty, then ectopic</div><div class=\"answer-line\">pregnancy is likely diagnosis, hence laparoscopy likely to be required</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 2 year old girl has been brought to the ED with a rash over her torso.\nA clinical image is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of this rash. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"What is the most likely diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"List 2 common infectious causes for this condition. (2 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List 4 non-infectious causes for this condition. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"e","label":"Part E","prompt":"State your management of this condition. (1 mark)"}],"propPages":["asset:img650e9cd7aa85134a2c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">- target lesions</div><div class=\"answer-line\">- erythematous macules</div><div class=\"answer-line\">- central sparing</div><div class=\"answer-line\">- various sizes</div><div class=\"answer-line\">- some confluence right abdomen</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Erythema multiforme</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Mycoplasma pneumoniae</div><div class=\"answer-line\">Viral eg HSV (need specific virus to get the mark)</div><div class=\"answer-line\">TB</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Antibiotics eg sulphonamides, penicillins</div><div class=\"answer-line\">Anticonvulsants eg phenytoin</div><div class=\"answer-line\">NSAIDs</div><div class=\"answer-line\">Haematological malignancies eg NHL, leukaemias</div><div class=\"answer-line\">Physical factors eg cold, radiotherapy</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Conservative / symptomatic</div><div class=\"answer-line\">Remove trigger</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 45 year old woman has been referred to the ED with hyperthyroidism, based on abnormal thyroid function tests (TFTs) performed in the community.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your examination that would be consistent with thyrotoxicosis.\n(4 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Complete the table by indicating the expected TFT results in primary and secondary hyperthyroidism. (2 marks) T4 TSH Primary hyperthyroidism Secondary hyperthyroidism"},{"id":"c","label":"Part C","prompt":"List 3 different causes of primary hyperthyroidism. For each, give a discriminatory\nexamination finding that would suggest its presence. (6 marks) Cause Examination finding"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Tachycardia</div><div class=\"answer-line\">AF</div><div class=\"answer-line\">Hyper-reflexia</div><div class=\"answer-line\">Thin habitus</div><div class=\"answer-line\">Tremor</div><div class=\"answer-line\">fever</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">elevated</div><div class=\"answer-line\">depressed</div><div class=\"answer-line\">elevated</div><div class=\"answer-line\">elevated</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>- Graves disease – eye signs eg exophthalmos</td><td>- thyroiditis – diffusely tender enlarged thyroid gland</td></tr><tr><td>- TMNG – large thyroid, irregular, lots of nodules</td><td>- toxic adenoma – unilateral lump in thyroid</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"You have been approached by a trainee who says they are being bullied by one of the other consultants within your ED.","parts":[{"id":"a","label":"Part A","prompt":"Provide a definition of bullying. (2 marks)"},{"id":"b","label":"Part B","prompt":"List 3 examples of bullying that might occur in the workplace. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"State 6 steps in your management of this situation. (6 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Unreasonable behaviour that creates a risk to health and safety.  Has to be repeated over time or</div><div class=\"answer-line\">occurs as a part of a pattern of behaviour.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Direct bullying – behaviour that is overt and usually involves conduct directed at a person to belittle</div><div class=\"answer-line\">or demean them. Examples include:</div><div class=\"answer-line\"> Aggressive and intimidating behaviour</div><div class=\"answer-line\"> Belittling, degrading or humiliating comments</div><div class=\"answer-line\"> Spreading misinformation or malicious rumours</div><div class=\"answer-line\"> Interfering with a persons property or work equipment</div><div class=\"answer-line\"> Displaying offensive material (e.g. pornography)</div><div class=\"answer-line\">(2) Indirect bullying – behaviour that excludes or removes benefits from a person. Examples include:</div><div class=\"answer-line\"> Assigning meaningless tasks unrelated to the job</div><div class=\"answer-line\"> Setting tasks that are unreasonably below or beyond a persons skill level</div><div class=\"answer-line\"> Deliberately changing work rosters to inconvenience particular employees</div><div class=\"answer-line\"> Deliberately withholding information that is vital for effective work performance</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">(scope of acceptable answers will be broad)</td></tr><tr><td>-</td><td>Meet with trainee / listen</td></tr><tr><td>-</td><td>Offer support person to be present</td></tr><tr><td>-</td><td>Discuss with director of the department</td></tr><tr><td>-</td><td>Document</td></tr><tr><td>-</td><td>Arrange appropriate channels of complaint if necessary – HR, Worksafe etc</td></tr><tr><td>-</td><td>Arrange appropriate work conditons eg shifts where appropriate until issue resolved</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 35 year old man has presented to the ED with a painful, red right eye for the past 2 days. A clinical photo is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 4 abnormalities in the image provided. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"What is the most likely diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"List 3 risk factors for this condition. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List 3 complications of this condition. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":["asset:imga2f32b30a60ed0afc4"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">- scleral injection</div><div class=\"answer-line\">- hypopyon</div><div class=\"answer-line\">- irregular pupil</div><div class=\"answer-line\">- cornea / anterior chamber cloudy</div><div class=\"answer-line\">- chemosis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Anterior uveitis / iritis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Inflammatory bowel disease</div><div class=\"answer-line\">Ankylosing spondylitis</div><div class=\"answer-line\">Sarcoidosis</div><div class=\"answer-line\">Psoriasis</div><div class=\"answer-line\">Reiter syndrome</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Synechiae</div><div class=\"answer-line\">Glaucoma</div><div class=\"answer-line\">Cataracts</div><div class=\"answer-line\">Retinitis</div><div class=\"answer-line\">Band keratopathy</div><div class=\"answer-line\">Also accept visual loss</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 70 year old man has been brought to the ED with chest pain and dizziness.\nHis ECG is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Give your interpretation of the ECG. (1 mark)"},{"id":"b","label":"Part B","prompt":"List 4 abnormalities from the ECG to support your interpretation. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"Complete the table by listing 3 possible causes of this problem. For each, provide a feature of your assessment (history, examination or investigation) that would support it as the underlying cause. (6 marks) Cause Assessment feature"},{"id":"d","label":"Part D","prompt":"List 2 medications you may use to manage this patient, including doses. (2 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________"}],"propPages":["asset:imge4631728a34465eec9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Ventricular tachycardia</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Broad complex approx. 160ms</div><div class=\"answer-line\">Regular tachycardia approx. 150/min</div><div class=\"answer-line\">Fusion beats 4 and 7</div><div class=\"answer-line\">Concordance across chest leads</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Ischaemia – signs on reversion ECG, Hx IHD, preceding chest pain</td><td>Electrolyte abnormality – hypoK on bloods</td></tr><tr><td>Drug toxicity – eg TCA ingestion</td><td>Primary arrhythmia – Hx cardiomyopathy eg ARVD</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Amiodarone 5mg/kg</div><div class=\"answer-line\">Lignocaine 1mg/kg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 9 year old boy has presented with a painful left wrist after falling off a swing in the playground. His x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 descriptive radiographical features of the injury. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ Your registrar is concerned about the possibility of median nerve injury, and is asking you for advice about how to test the function of the median nerve."},{"id":"b","label":"Part B","prompt":"List 3 examination features that would suggest injury to the median nerve at the level of\nthe wrist. (3 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ The median nerve function is normal."},{"id":"c","label":"Part C","prompt":"State 5 important components of your management of this case. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________"}],"propPages":["asset:img0e1258bcce7ed13ea3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Salter Harris 1 injury distal radius</div><div class=\"answer-line\">Dorsal displacement of epiphysis</div><div class=\"answer-line\">Dorsal angulation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Sensory loss palm lateral 3 ½ digits</div><div class=\"answer-line\">Motor loss thumb opposition</div><div class=\"answer-line\">Motor loss thumb abduction</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Explanation / consent with patient and parents</div><div class=\"answer-line\">Analgesia – any options will be OK</div><div class=\"answer-line\">Procedural sedation – eg ketamine 0.5mg/kg</div><div class=\"answer-line\">Reduction of epiphysis either procedural sedation or in OT</div><div class=\"answer-line\">Plaster – short arm plaster</div><div class=\"answer-line\">Orthopaedic follow up – fracture clinic if reduced well</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 65 year old woman has been brought to the ED after striking her head when falling down some stairs at her home.","parts":[{"id":"a","label":"Part A","prompt":"List 6 findings on your history or examination that would indicate a need for neuroimaging in this patient. (6 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________ A CT scan of her head is provided in the PROPS BOOKLET."},{"id":"b","label":"Part B","prompt":"List 4 abnormalities on the image provided. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ There are no other injuries evident on assessment."},{"id":"c","label":"Part C","prompt":"List and justify 4 other investigations you would perform on this patient. (8 marks)"}],"propPages":["asset:img5c02680c33585c7d2e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>14/18</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Reduced GCS</div><div class=\"answer-line\">Focal neurological signs</div><div class=\"answer-line\">On anti-coagulation</div><div class=\"answer-line\">Signs BOS # or depressed skull fracture</div><div class=\"answer-line\">Vomiting</div><div class=\"answer-line\">amnesia</div><div class=\"answer-line\">Anything else reasonable</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Acute on subacute subdural haematoma / haemorrhage</div><div class=\"answer-line\">High attenuation anterior – acute blood</div><div class=\"answer-line\">Iso-attenuation – subacute blood</div><div class=\"answer-line\">Loss of sulci left hemisphere – raised ICP</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">ECG – look for arrhythmogenic cause of fall</div><div class=\"answer-line\">Coag – exclude coagulopathy which would require correction</div><div class=\"answer-line\">Platelet count – exclude as exacerbating factor – correct if low</div><div class=\"answer-line\">Accept other causes of fall – Na, urine</div><div class=\"answer-line\">Accept other consequences of fall if justified – CXR, c-spine, pelvis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 55 year old man suffering from a myocardial infarction has been retrieved from a rural hospital. He was treated with aspirin, heparin and intravenous morphine in appropriate doses at the rural ED.\nHe was given tenecteplase 1 hour and 45 minutes ago.\nOn arrival to your tertiary ED, he looks pale and sweaty and is complaining of severe chest pain. His ECG on arrival to your ED is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"What is the main pathology demonstrated? (1 mark)"},{"id":"b","label":"Part B","prompt":"List 4 features of the ECG that support your answer. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________\nHis vital signs are:\n\nGCS\n\nBP\n80/40 mmHg O2 saturation 99% 6L O2 via Hudson mask"},{"id":"c","label":"Part C","prompt":"List 3 management steps you would perform. Provide justification for each step.\n(6 marks) Management step Justification Shortly after arrival, the patient develops complete heart block with a ventricular escape rhythm.\nHis vital signs are now:\n\nGCS\nE4 V4 M6 Pulse /minute\n\nBP\n70/35 mmHg You have decided to electrically pace the patient."},{"id":"d","label":"Part D","prompt":"State 5 steps in the successful initiation of electrical pacing. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________"}],"propPages":["asset:img66703b86f9ee8f1d2c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>11/18</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Infero-lateral STEMI</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">ST elevation inferior (II, III, aVF) and lateral leads (V5 V6)</div><div class=\"answer-line\">ST depression V1 – V3 posterior STEMI</div><div class=\"answer-line\">Reciprocal depression I aVL</div><div class=\"answer-line\">Sinus bradycardia ~55/min</div><div class=\"answer-line\">STE III&gt;II c/w RV infarction</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>IV fluid bolus N/S 500mL to improve preload RV</td><td>Urgent cardiology referral for rescue angioplasty given failed reperfusion</td></tr><tr><td>Analgesia – IV morphine 2.5mg aliquots for pt comfort</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Consent / explanation</div><div class=\"answer-line\">Place pads – AP or antero-lateral</div><div class=\"answer-line\">Sedation / analgesia (reasonable agents / doses)</div><div class=\"answer-line\">Set demand pacing rate 60-80, current enough to get capture</div><div class=\"answer-line\">Ensure electrical and mechanical capture</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 45 year old man has presented with colicky central abdominal pain.\nYour assessment is consistent with small bowel obstruction.","parts":[{"id":"a","label":"Part A","prompt":"List 3 causes of small bowel obstruction. For each, state a feature of your history or\nexamination that would suggest its presence. (6 marks) Cause Feature of history or examination"},{"id":"b","label":"Part B","prompt":"List 3 complications of small bowel obstruction. For each, state the management\nprinciples. (6 marks) Complication Management principles"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Adhesions – previous abdominal surgeries, abdominal scars</td><td>Herniae – presence of inguinal or other herinia on exam</td></tr><tr><td>Malignancy – known Hx malignancy, wt loss</td><td>Stricture – Hx Crohns disease</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Ischaemia, Perforation – urgent surgery, antibiotics</td><td>Hypovolemia – IV fluid replacement</td></tr><tr><td>Electrolyte abnormalities eg hypokalaemia – replace K</td><td>Others may be OK</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 56 year old man has presented with severe right sided flank pain.\nA CT scan has been performed. Two slices (non-contiguous) are provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities on the imaging provided. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 3 further investigations you would perform, with justification. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ On review of this man’s medical history, you note that he has had 12 CT scans in the previous year. You have decided to write a management plan for his future presentations to the ED, aiming to minimise radiation exposure."},{"id":"c","label":"Part C","prompt":"State 5 points in your plan. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________"}],"propPages":["asset:img2d36257dabe05c2ff3","asset:imge1c88dcd6ec1e82858"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">R hydronephrosis</div><div class=\"answer-line\">R perinephric fat stranding</div><div class=\"answer-line\">Small stone R VUJ</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Urine micro – to exclude UTI which would require a stent</div><div class=\"answer-line\">Urea, creatinine – determine whether significant renal failure</div><div class=\"answer-line\">x-ray KUB – determine whether radio-opaque for surveillance</div><div class=\"answer-line\">serum urate – may point to hyperuricaemia as cause for urate stones</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">- plan to be used when patient presents with symptoms of renal colic</div><div class=\"answer-line\">- provide adequate analgesia eg IV morphine 2.5mg aliquots</div><div class=\"answer-line\">- check urine to exclude UTI</div><div class=\"answer-line\">- check renal function to exclude significant ARF</div><div class=\"answer-line\">- manage symptomatically initially:</div><div class=\"answer-line\">If pain settles with above management and no UTI / ARF then discharge no imaging</div><div class=\"answer-line\">If pain not settling then USS first choice to exclude hydronephrosis</div><div class=\"answer-line\">-</div><div class=\"answer-line\">CT unlikely to be indicated in the absence of hydronephrosis</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Involve Urology team prior to ordering CT scan</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 25 year old man has been taken to the ED after an overdose of insulin 30 minutes ago.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your toxicological history. For each, state the relevance to your\nmanagement. (8 marks) Historical feature Relevance to management The patient is hypoglycaemic and responds to a 25mL intravenous bolus of 50% dextrose. He is subsequently alert, with normal vital signs."},{"id":"b","label":"Part B","prompt":"List 2 steps, with end-points in your management of his overdose. (2 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Type of insulin – will affect duration of toxicity and observation</td><td></td></tr><tr><td>-</td><td>Amount – will affect severity of duration of toxicity</td></tr><tr><td>-</td><td>Multiple sites / one site – one site makes a depot with longer duration of release / toxicity</td></tr><tr><td>-</td><td>Diabetic or not – affects how you wean glucose infusion</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">- IV dextrose infusion – aiming for BSL above 3.5</div><div class=\"answer-line\">- IV potassium infusion aiming for normal range</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 75 year old woman has collapsed while doing her shopping.\nOn arrival to the ED, she is complaining of severe abdominal pain radiating to her back. An image from a bedside USS of her abdomen is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State the identified pathology. (1 mark)"},{"id":"b","label":"Part B","prompt":"State 3 considerations that would influence your decision to perform a CT scan on this\npatient. (3 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ The patient’s vital signs are:\n\nGCS\nE2 V3 M5 Pulse 135 /min\n\nBP\n65/35 mmHg She is pale and sweaty."},{"id":"c","label":"Part C","prompt":"State 3 key components of your management. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List 3 definitive management options for this patient. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":["asset:img8af5e8bb4e208a3a75"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Abdominal aortic aneurysm</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Haemodynamic status – dangerous to transport a shocked patient to the CT scanner</div><div class=\"answer-line\">Proximity to CT – more able to scan a sick patient if CT is in the resus room</div><div class=\"answer-line\">Pre-surgical planning requirement – placing a stent requires good knowledge of pathology /</div><div class=\"answer-line\">anatomy of the patient, CT required for this option</div><div class=\"answer-line\">Pt characteristics that would suggest palliation is the only suitable management</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Immediate vascular surgical referral for OT</div><div class=\"answer-line\">Blood administration – 1 unit packed cells aiming for cerebral perfusion, radial pulse, systolic</div><div class=\"answer-line\">80mmHg</div><div class=\"answer-line\">Analgesia – small boluses – eg fentanyl 20mcg for comfort</div><div class=\"answer-line\">Family / NOK meeting – high mortality in this situation</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">OT – open repair</div><div class=\"answer-line\">Endovascular stent</div><div class=\"answer-line\">palliation</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 3 year old girl has been brought to the ED with a headache and fever.\nHer vital signs are:\n\nWeight\nkg\n\nGCS\nE4 V4 M6 Pulse 180 /min\n\nBP\n75/40 mmHg Temperature 39.0 degrees You are concerned about the possibility of bacterial meningitis.","parts":[{"id":"a","label":"Part A","prompt":"State 3 steps in your management plan. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ A lumbar puncture has been performed. The results are given in the PROPS BOOKLET."},{"id":"b","label":"Part B","prompt":"What is the most likely diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"State 2 features of the CSF result that support your diagnosis. (2 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List 3 potential pathogens. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"},{"id":"e","label":"Part E","prompt":"List 3 further tests you would perform to identify the pathogen. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":["asset:imgca0c1f682f0e893c78"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">IV fluid 10-20mL/kg N/S aiming for pulse &lt;160, BP maintain &gt;85-90mmHg</div><div class=\"answer-line\">IV dexamethasone 0.15mg/kg up to 10mg</div><div class=\"answer-line\">IV ceftriaxone 50-100mg/kg</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Bacterial meningitis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Predominantly neutrophilic raised WBC</div><div class=\"answer-line\">High protein and low glucose</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Streptococcus pneumoniae</div><div class=\"answer-line\">Neisseria meningiditis</div><div class=\"answer-line\">Haemophilus influenza</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Blood cultures</div><div class=\"answer-line\">Strep Ag – urine</div><div class=\"answer-line\">Neisseria PCR – blood</div><div class=\"answer-line\">CSF gram stain / culture</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 45 year old alcoholic man has presented with haematemesis. He is known to have chronic liver disease. You suspect variceal haemorrhage.\nHis vital signs are:\n\nGCS\nE4 V4 M5 Pulse 120 /min\n\nBP\n80/40 mmHg\nO2 saturation 98%\nroom air","parts":[{"id":"a","label":"Part A","prompt":"List and justify 4 investigations you would perform on this patient. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 4 haematological parameters you would target in your management. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"Apart from fluid resuscitation, state 3 steps in your management of this patient. (3 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">VBG – assess degree of hypoperfusion – lactate / base excess</div><div class=\"answer-line\">Hb – will guide packed cell replacement</div><div class=\"answer-line\">Coag – high chance of liver disease, will guide FFP therapy</div><div class=\"answer-line\">Fibrinogen / Ca – also will require replacement if low to manage coagulopathy</div><div class=\"answer-line\">BSL – pt likely to have a degree of liver failure, replace if needed</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hb &gt;70</div><div class=\"answer-line\">INR &lt;1.6</div><div class=\"answer-line\">Plt &gt;50</div><div class=\"answer-line\">Fibrinogen &gt;1.0</div><div class=\"answer-line\">Ionised Ca normal range</div><div class=\"answer-line\">Also accept normal ROTEM parameters</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Urgent endoscopy for variceal banding</div><div class=\"answer-line\">IV octreotide 50mcg bolus, 50mcg/hr</div><div class=\"answer-line\">IV antibiotics for gram neg cover – eg ceftriaxone 1g</div><div class=\"answer-line\">Also accept prevention of alcohol withdrawal with diazepam</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 5 year old boy has been carried to triage by his father. He has been unwell with an exacerbation of asthma but has deteriorated in the last hour. On assessment in your resuscitation room, the patient is cyanosed and not breathing. You cannot feel a pulse. Cardiac monitoring shows sinus rhythm at a rate of 60 beats per minute.","parts":[{"id":"a","label":"Part A","prompt":"State your 4 main management priorities, including relevant details. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ The nurse in charge has asked you whether the child’s father can be present for the resuscitative effort."},{"id":"b","label":"Part B","prompt":"List 2 pros and 2 cons regarding parental presence in this situation.\n(4 marks) Pros Cons The patient died in the ED. Many staff members are visibly distressed. The nurse in charge has asked if you could lead a debrief session for the entire team involved."},{"id":"c","label":"Part C","prompt":"State 4 features of your management of the debrief session. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Start CPR – 15:2, 100/min</div><div class=\"answer-line\">IV adrenaline 10mcg/kg</div><div class=\"answer-line\">IV fluid bolus 20mL/kg N/S</div><div class=\"answer-line\">Early intubation due to hypoxia being most likely problem, 100% O2</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pros</div><div class=\"answer-line\">allows parents to be with child as is the usual preference</div><div class=\"answer-line\">Helps with grieving</div><div class=\"answer-line\">Cons</div><div class=\"answer-line\">can make caregivers feel uncomfortable</div><div class=\"answer-line\">In extreme situations, parent might interfere with efforts</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Arrange time when all those who wish to be involved can be, ie rest of department must be covered</div><div class=\"answer-line\">Allow people to express their concerns /  grief</div><div class=\"answer-line\">Emphasize no blame culture</div><div class=\"answer-line\">Ensure team are aware of the poor prognosis from arrival of patient</div><div class=\"answer-line\">Offer options for ongoing support</div><div class=\"answer-line\">Offer time out where needed</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 35 year old man has presented to the ED with 24 hours of progressive breathlessness.\nOn assessment, he has increased work of breathing and is hypoxic on room air. A chest x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities on the chest x-ray. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"In the table below, list 2 differential diagnoses for the patient’s presentation. For each, list 3 investigative findings that would help confirm the diagnosis. (8 marks) Differential diagnosis Investigative finding An arterial blood gas taken from the patient is provided in the PROPS BOOKLET."},{"id":"c","label":"Part C","prompt":"State the 2 major acid-base disturbances present, with supporting evidence from the\nblood gas result. (4 marks) Acid-base disturbance Supporting evidence"},{"id":"d","label":"Part D","prompt":"Complete the following table regarding the blood gas results. (9 marks) Formula Calculated result Clinical implication Anion gap Delta gap / ratio Alveolar - arterial\n• xygen\ngradient"}],"propPages":["asset:imgfa1a14630e8fbfb860","asset:img85dacad34c097feb9a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>16/24</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Left midzone opacities (confluent, suggesting alveolar infiltrates)</div><div class=\"answer-line\">Right mid zone opacification obliterating R cardiac silhouette</div><div class=\"answer-line\">Kerley B lines (best seen in R lung field)</div><div class=\"answer-line\">Small left effusion</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Differential Diagnosis</td><td>Further Investigations</td></tr><tr><td>CAP</td><td>Blood Cultures</td></tr><tr><td>Sputum Culture</td><td></td></tr><tr><td>Urinary Ag</td><td></td></tr><tr><td>(others – NPA, CRP?)</td><td></td></tr><tr><td>Cardiac Failure</td><td>ECHO</td></tr><tr><td>Troponin</td><td></td></tr><tr><td>BNP</td><td></td></tr><tr><td>Ultrasound for B-lines</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Respiratory acidosis – raised CO2 61, low pH</div><div class=\"answer-line\">High anion gap metabolic acidosis -  Low HCO3, raised AG 17, low pH</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>AG</td><td>Na – (Cl + HCO3)</td><td>17</td><td>most likely lactic acidosis due to cellular</td></tr><tr><td colspan=\"4\">hypoperfusion</td></tr><tr><td>DG</td><td>change AG:change HCO3</td><td>5:5</td><td>pure high AG met acidosis</td></tr><tr><td>A:a</td><td>[FiO2*713 – pCO2/0.8] – pO2</td><td>very high</td><td>means there is a significant shunt as many</td></tr><tr><td colspan=\"4\">alveoli are not oxygenated – implies severe gas exchange problem</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 16 year old indigenous man has presented to your rural ED with lethargy and malaise.\nYou are considering the diagnosis of acute rheumatic fever.","parts":[{"id":"a","label":"Part A","prompt":"List the 5 major Jones criteria for the diagnosis of acute rheumatic fever. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ The patient has acute rheumatic fever. You note that he presented twice to the ED in the last month with a sore throat and was discharged\n• n both occasions with a diagnosis of viral URTI."},{"id":"b","label":"Part B","prompt":"List 2 potential contributory factors in each of the following areas that could have led to this situation. (6 marks) Potential contributory factors System Process Individual"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Carditis</div><div class=\"answer-line\">Sydenhams chorea</div><div class=\"answer-line\">Erythema marginatum</div><div class=\"answer-line\">Rheumatic nodules</div><div class=\"answer-line\">Arthritis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>System</td><td>not enough doctors, too busy for adequate supervision of junior staff,</td></tr><tr><td>Process</td><td>no policy for senior discussion of each case, lack of education around rheumatic</td></tr><tr><td colspan=\"2\">fever in indigenous population</td></tr><tr><td>Individual</td><td>junior doctor / inexperienced, any sort of personal problem</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"You are working as an aeromedical retrieval consultant. You have been tasked to a remote community to retrieve a patient who has presented with an exacerbation of schizophrenia.","parts":[{"id":"a","label":"Part A","prompt":"List 6 features on history or examination that would indicate a potential threat to patient and staff safety during transport. (6 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 3 drugs, with doses, that you might employ as chemical sedation to facilitate safe\nretrieval of the patient. (3 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List 3 other strategies you might employ to facilitate safe management of this patient.\n(3 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Threats of violence</div><div class=\"answer-line\">Active thought disorder</div><div class=\"answer-line\">Inability to follow commands</div><div class=\"answer-line\">Current intoxication</div><div class=\"answer-line\">History of violence</div><div class=\"answer-line\">Evidence of significant self-harm</div><div class=\"answer-line\">Lots of others acceptable</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Diazepam 10mg oral prn</div><div class=\"answer-line\">Ketamine 20mg aliquots prn, or infusion</div><div class=\"answer-line\">Droperidol 10mg IM</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Avoid air transport altogether – ground transport</div><div class=\"answer-line\">Employ police / security to travel with pt</div><div class=\"answer-line\">Intubate for transfer / general anaesthesia</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 44 year old woman has been struck by a car while walking across a road. She has sustained an isolated right knee injury. An AP x-ray of her right knee is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 4 abnormalities shown in the x-ray. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Provide the name and grade of this injury using a recognised classification system. (1 mark)"},{"id":"c","label":"Part C","prompt":"List 3 important associated injuries. For each, list a specific examination finding that\nwould support its presence. (6 marks) Associated injury Supportive examination finding"}],"propPages":["asset:img4507fd1acde5c79b0c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Tibial plateau fracture</div><div class=\"answer-line\">Comminuted</div><div class=\"answer-line\">Both lateral and medial condyles involved</div><div class=\"answer-line\">Lateral displacement of knee</div><div class=\"answer-line\">Head of fibula comminuted fracture</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Schatzker 6</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Popliteal artery dissection / injury – loss of dorsalis pedis pulse, leg cold, painful</td><td>Common peroneal nerve injury – foot drop, sensory dorsum foot</td></tr><tr><td>Posterior tibial nerve injury – loss plantar flexion, loss sensation sole of foot</td><td>Compartment syndrome – extreme pain, tense compartment , loss neurovascular function</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 2 year old boy has been brought to your ED with heat stroke after being left in a hot car. He has suffered prolonged seizure activity. On arrival to the ED, his vital signs are: AVPU unresponsive with ongoing seizure activity Pulse 160 /min\n\nBP\n80/35 mmHg O2 sats 99% 15L O2 via non-rebreather mask\n\nTemp\n41.0 degrees","parts":[{"id":"a","label":"Part A","prompt":"List and justify 4 investigations you would initiate. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ You plan to intubate the patient as part of your early management."},{"id":"b","label":"Part B","prompt":"Complete the table regarding your rapid sequence induction. (4 marks) Appropriate choice Endotracheal tube size Length of tube at teeth Induction agent with dose Paralysis agent with dose"},{"id":"c","label":"Part C","prompt":"State 3 strategies you would employ for cooling this patient in the ED. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1.</div><div class=\"answer-line\">a.<strong> </strong>BSL – potential reversible cause seizures</div><div class=\"answer-line\">b. Na+ - cause of seizures in setting heat stroke</div><div class=\"answer-line\">c. ECG to exclude hyperkalaemia, other arrhythmias</div><div class=\"answer-line\">d. CK degree of rhabdomyolysis (renal function also ok)</div><div class=\"answer-line\">e. K+ rhabdo and possible renal failure in heat stroke</div><div class=\"answer-line\">f. CT head – intracranial haemorrhage as a complication of seizures</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">2.</div><div class=\"answer-line\">4.5</div><div class=\"answer-line\">13cm</div><div class=\"answer-line\">Ketamine 1mg/kg, propofol 0.5 - 1mg/kg</div><div class=\"answer-line\">Suxamethonium 1-2mg/kg, rocuronium 1.2mg/kg</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">d. CK degree of rhabdomyolysis (renal function also ok)</div><div class=\"answer-line\">e. K+ rhabdo and possible renal failure in heat stroke</div><div class=\"answer-line\">f. CT head – intracranial haemorrhage as a complication of seizures</div><div class=\"answer-line\">2.</div><div class=\"answer-line\">4.5</div><div class=\"answer-line\">13cm</div><div class=\"answer-line\">Ketamine 1mg/kg, propofol 0.5 - 1mg/kg</div><div class=\"answer-line\">Suxamethonium 1-2mg/kg, rocuronium 1.2mg/kg</div><div class=\"answer-line\">3.</div><div class=\"answer-line\">Remove clothing</div><div class=\"answer-line\">Water spray and fans</div><div class=\"answer-line\">Cold IV fluid</div><div class=\"answer-line\">Cold fluid bladder lavage</div><div class=\"answer-line\">Cooling blanket</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 72 year old man has presented with epistaxis.","parts":[{"id":"a","label":"Part A","prompt":"List 3 features in your history or examination that would be suggestive of a posterior\nsource of bleeding. (3 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ Your assessment is suggestive of an anterior source of bleeding."},{"id":"b","label":"Part B","prompt":"List 5 escalating strategies you could employ to treat this man’s bleeding. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ The patient is taking warfarin."},{"id":"c","label":"Part C","prompt":"State 4 considerations you would have in deciding upon your actions around warfarin\nreversal. (4 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bilateral epistaxis</div><div class=\"answer-line\">Large amount of posterior nasopharyngeal blood</div><div class=\"answer-line\">Bleeding not controlled with anterior techniques</div><div class=\"answer-line\">Hx nasopharyngeal malignancy</div><div class=\"answer-line\">Hx recent surgery nasopharynx</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Direct pressure on anterior nares</div><div class=\"answer-line\">Cold/ ice pack to nose</div><div class=\"answer-line\">Direct cautery</div><div class=\"answer-line\">Anterior packing with pre-made pack eg merocel tampon or “rapid rhino”</div><div class=\"answer-line\">Anterior and posterior packing</div><div class=\"answer-line\">Interventional radiological embolization</div><div class=\"answer-line\">OT with ENT</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Ability to control bleeding with initial basic measures ie need for correction on INR</div><div class=\"answer-line\">Actual INR – supra-therapeutic more likely to correct</div><div class=\"answer-line\">Risk of complication due to correction ie metallic valve try to avoid correction unless necessary due</div><div class=\"answer-line\">to risk of stroke</div><div class=\"answer-line\">Need to re-institute anti-coagulation quickly – avoid vit K if need to restart warfarin quickly eg</div><div class=\"answer-line\">metallic valve</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 24 year old man has been brought to the ED after diving in to a shallow pool while intoxicated. His cervical spine x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State the injury identified in the x-ray. (1 mark)"},{"id":"b","label":"Part B","prompt":"List 4 abnormalities in the x-ray that support your conclusion. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List 3 possible early complications of this presentation. State how you would manage each\ncomplication. (6 marks) Complication Management"}],"propPages":["asset:img9fef331cd9cc31352e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">C4/5 bilateral facet joint dislocation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pre-vertebral soft tissue swelling in front of C5</div><div class=\"answer-line\">Anterior listhesis C4 on C5 &gt;50% vertebral body</div><div class=\"answer-line\">Loss posterior spinal line</div><div class=\"answer-line\">Bilateral perched facets</div><div class=\"answer-line\">Widened space between C4/5 spinous processes</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hypoventilation / respiratory failure – intubate and ventilate, aim CO2 normal</div><div class=\"answer-line\">Neurogenic shock – IV N/S boluses and noradrenaline infusion aiming for MAP &gt;65mmHg</div><div class=\"answer-line\">Hypoxia due to aspiration lung injury – intubate, high FiO2 aiming for pO2 &gt;60mmHg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 42 year old man has presented to the ED with abdominal pain and jaundice.\nHis liver function tests are provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State your interpretation of the results provided, with justification. (3 marks)"},{"id":"b","label":"Part B","prompt":"List 4 non-infectious causes of this pattern of disease. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List, with justification, 5 investigations you would perform in the further assessment of this patient. (5 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________"}],"propPages":["asset:imgb9dc30618604b943e0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Unconjugated hyperbilrubinaemia: raised bili, low fraction conjugated</div><div class=\"answer-line\">Hepatocellular pattern ALT and AST &gt;  GGT and ALP consistent with hepatitis</div><div class=\"answer-line\">Low albumin probably due to liver synthetic dysfunction, also maybe acute phase response due to</div><div class=\"answer-line\">inflammation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Paracetamol toxicity</div><div class=\"answer-line\">Alcohol</div><div class=\"answer-line\">NASH</div><div class=\"answer-line\">Autoimmune</div><div class=\"answer-line\">Ischaemic hepatitis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hepatitis serology A,B,C – for cause of hepatitis (max 1 mark)</div><div class=\"answer-line\">Paracetamol level – for cause, treatment for this is available</div><div class=\"answer-line\">BSL – hypoglycaemia in fulminant synthetic dysfunction</div><div class=\"answer-line\">Coags – synthetic dysfunction</div><div class=\"answer-line\">Autoimmune markers – for diagnosis</div><div class=\"answer-line\">Electrolytes – low Na common complication of liver disease</div><div class=\"answer-line\">USS abdomen – define liver architexture eg cirrhosis, exclude portal vein thrombosis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 3 week old boy has been brought to the ED by his mother. The child is not feeding well and has failed to gain weight since birth.","parts":[{"id":"a","label":"Part A","prompt":"List 5 features of your examination, including the relevance of each feature. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List and justify 5 investigations you might perform. (5 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Vital signs – shocked child from any cause esp sepsis, congenital heart problems, urgent</div><div class=\"answer-line\">resuscitation may be required</div><div class=\"answer-line\">Weight, length, head circumference – to plot on growth chart and compare with birth</div><div class=\"answer-line\">Fontanelle – raised ICP eg from NAI would have bulging fontanelle</div><div class=\"answer-line\">Chest exam – looking for pulmonary oedema or other respiratory dysfunction that would impair</div><div class=\"answer-line\">feeding</div><div class=\"answer-line\">CVS – murmurs / hepatomegaly / coarctation</div><div class=\"answer-line\">Jaundice – at this age would indicate serious pathology eg biliary atresia</div><div class=\"answer-line\">Bruising – NAI</div><div class=\"answer-line\">Many other reasonable answers</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">BSL – hypoglycaemia in metabolic conditions, sepsis</div><div class=\"answer-line\">ECG – tachyarrhythmias can present as failure to thrive</div><div class=\"answer-line\">VBG – assess degree of hypoperfusion – eg lactate / metabolic acidosis</div><div class=\"answer-line\">Bilirubin / LFTs – esp if jaundiced – exclude congenital liver problem</div><div class=\"answer-line\">FBC – anaemia from congenital haemolytic cause</div><div class=\"answer-line\">Septic screen – urine / CXR / LP where indicated from examination to exclude infection</div><div class=\"answer-line\">Urine for metabolic screen – where suggested by hx or metabolic acidosis</div><div class=\"answer-line\">Others OK</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
